Type":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="en">

<head>
  <meta charset="UTF-8">
  <meta http-equiv="X-UA-Compatible" content="IE=edge">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Document</title>
  <style>
    /* Centering the button */
    #save-btn {
      display: block;
      margin: 0 auto;
      padding: 20px 35px;
      font-size: 16px;
      border-radius: 0;
      float:;
    }
  </style>
</head>

<body>
  <button id="save-btn">Save Contact</button>

  <script>
    var saveBtn = document.getElementById("save-btn");
    saveBtn.addEventListener("click", function () {
      // Get the contact information from the website
      var contact = {
        name: "Paul Richards",
        phone: "+447734690272",
        email: "paul@onixdatacentres.com"
      };
      // create a vcard file
      var vcard = "BEGIN:VCARD\nVERSION:4.0\nFN:" + contact.name + "\nTEL;TYPE=work,voice:" + contact.phone + "\nEMAIL:" + contact.email + "\nEND:VCARD";
      var blob = new Blob([vcard], { type: "text/vcard" });

      // For Android devices, use the download attribute to trigger file download
      if (navigator.userAgent.match(/Android/i)) {
        var link = document.createElement('a');
        link.setAttribute('href', window.URL.createObjectURL(blob));
        link.setAttribute('download', contact.name + ".vcf");
        link.style.display = 'none';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      } else { // For other devices, create a link and simulate click
        var url = URL.createObjectURL(blob);
        const newLink = document.createElement('a');
        newLink.download = contact.name + ".vcf";
        newLink.href = url;
        newLink.style.display = 'none';
        document.body.appendChild(newLink);
        newLink.click();
        document.body.removeChild(newLink);
      }
    });
  </script>
</body>

</html>
